import{_ as o,o as e,c as t,Q as a}from"./chunks/framework.b67c47e6.js";const n="/assets/account-page.835fd5d3.svg",f=JSON.parse('{"title":"Account Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/account/index.md","filePath":"guide/account/index.md","lastUpdated":1792752419000}'),i={name:"guide/account/index.md"},r=a('<h1 id="account-settings" tabindex="-1">Account Settings <a class="header-anchor" href="#account-settings" aria-label="Permalink to &quot;Account Settings&quot;">​</a></h1><p>The Account page shows who you are and where you work, and lets you set up how you sign in, your language and the notifications you get. Open it from the account button at the top of the left menu: <strong>Account</strong>.</p><p><img src="'+n+'" alt="The Account page"></p><ol><li>Your profile: username, email, alias and language.</li><li>Your workplace: company, role and station.</li><li>Two-factor authentication and Google or Microsoft sign-in.</li><li>Which messages you get, and the emails about them.</li><li>The applications you connected, such as Claude.</li></ol><p>On a wide screen the page has two columns, as above. On a smaller screen, and on a phone, the same cards follow each other in one column, in the order of the numbers.</p><p>Every setting on this page is saved as soon as you change it. There is no <strong>Save</strong> button.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><ul><li><strong>Username</strong> — Your login name.</li><li><strong>Email</strong> — The email of your account, or <em>No email</em>.</li><li><strong>Alias</strong> — How you are named on the factory floor. Shown only when it differs from your username.</li><li><strong>Language</strong> — The language of the interface. Shown only if multilanguage is enabled for your account.</li></ul><h2 id="workplace" tabindex="-1">Workplace <a class="header-anchor" href="#workplace" aria-label="Permalink to &quot;Workplace&quot;">​</a></h2><ul><li><strong>Company</strong> — The company your account belongs to.</li><li><strong>Role</strong> — What your account may do: company administrator, company manager, production user or external viewer.</li><li><strong>Production station</strong> — The line and station you work at, or <em>No station</em>. Change it from the account menu in the left menu.</li></ul><h2 id="sign-in-and-security" tabindex="-1">Sign-in and security <a class="header-anchor" href="#sign-in-and-security" aria-label="Permalink to &quot;Sign-in and security&quot;">​</a></h2><h3 id="two-factor-authentication" tabindex="-1">Two-factor authentication <a class="header-anchor" href="#two-factor-authentication" aria-label="Permalink to &quot;Two-factor authentication&quot;">​</a></h3><p>With two-factor authentication on, signing in asks for a code from an authenticator app on your phone, as well as your password. The row says whether it is <strong>On</strong> or <strong>Off</strong>.</p><p>To turn it on:</p><ol><li>Click <strong>Set up</strong>.</li><li>Scan the QR code with your authenticator app (Google Authenticator, Authy, etc.).</li><li>Enter the 6-digit code the app shows and click <strong>Turn on</strong>.</li></ol><p>To turn it off, click <strong>Turn off</strong>, then <strong>Turn off</strong> again to confirm.</p><h3 id="linked-accounts" tabindex="-1">Linked accounts <a class="header-anchor" href="#linked-accounts" aria-label="Permalink to &quot;Linked accounts&quot;">​</a></h3><p>Link a Google or Microsoft account to sign in faster. Use the Google sign-in button, or <strong>Link</strong> next to Microsoft, and <strong>Unlink</strong> to remove a link. Linking replaces your account email with the provider&#39;s. A provider that is not set up shows <em>Not available</em>.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><ul><li><strong>Messages in the app</strong> — One switch per kind of system message you receive in your produuz.it messages: <strong>Errors on report generation</strong>, <strong>Produuz.it updates</strong>, <strong>Panels marked as ready</strong> and <strong>Batches marked as ready</strong>.</li><li><strong>Emails</strong> — When you get an email about messages you receive: never, on each message, when a message is not read within 5 minutes, or one email at the end of the day with all messages.</li></ul><h2 id="connected-apps" tabindex="-1">Connected Apps <a class="header-anchor" href="#connected-apps" aria-label="Permalink to &quot;Connected Apps&quot;">​</a></h2><p><strong>Connected apps</strong> lists the applications you have allowed to read your produuz.it data, such as an AI assistant connected through <a href="/guide/mcp/">MCP</a>. For each one you see what it may access and when it was last used; an app marked <em>not reviewed</em> has not been checked by produuz.it. Click <strong>Disconnect</strong> to revoke its access.</p>',22),s=[r];function c(l,u,h,d,g,p){return e(),t("div",null,s)}const y=o(i,[["render",c]]);export{f as __pageData,y as default};
